    (1, 653, 'RESISTENCIA P/ VAPORIZADOR MOD 4T46X66 800W', 2, 1, 'ACTIVO', 'A', 0, 1, 'S', null, null, null, 626, 1, 1, 1, 'RESISTENCIA', 'RESISTENCI P/VAPORIZADOR MOD 4T46X66 800W', 'PRC50', null, 'PRC50', 'PRC50', null, null, 653, false, null, false, 0, 'NO', null),
